import{_ as a,o as s,c as e,a1 as d}from"./chunks/framework.DdbKPUhY.js";const k=JSON.parse('{"title":"嵌入式与长期运行","description":"UVHTTP 嵌入式与长跑指标：持续负载下 RSS 持平（60s 零增长）、静态库 ~257 KB、冷启动 ~310ms、支持 32 位。ASan-clean 内存安全保证的运行时佐证。","frontmatter":{"title":"嵌入式与长期运行","sync_hash":"5a26c78ba54717d041c4fde52fcf1efa0586cc9c","description":"UVHTTP 嵌入式与长跑指标：持续负载下 RSS 持平（60s 零增长）、静态库 ~257 KB、冷启动 ~310ms、支持 32 位。ASan-clean 内存安全保证的运行时佐证。"},"headers":[],"relativePath":"zh/embedded-profile.md","filePath":"zh/embedded-profile.md"}'),i={name:"zh/embedded-profile.md"};function h(n,t,l,r,o,p){return s(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="嵌入式与长期运行性能画像" tabindex="-1">嵌入式与长期运行性能画像 <a class="header-anchor" href="#嵌入式与长期运行性能画像" aria-label="Permalink to &quot;嵌入式与长期运行性能画像&quot;">​</a></h1><p>单机峰值吞吐并非 UVHTTP 的卖点（这方面 nginx 与 h2o 更胜一筹）。对于嵌入式设备与长期运行的服务，真正关键的指标是另一组：<strong>内存在数天的运行时间内是否保持平稳？占用的体积能多小？能否在 32 位上运行？启动有多快？</strong> 本页回答这些问题。</p><p>这些测量是<a href="./MEMORY_SAFETY.html">内存安全保证</a>的补充：消毒器干净的状态告诉你<em>从构造上不存在泄漏</em>；下方的长期运行 RSS 画像则展示了它<em>在持续负载下的实际表现</em>。</p><h2 id="长期运行内存稳定性-持续负载下无泄漏" tabindex="-1">长期运行内存稳定性（持续负载下无泄漏） <a class="header-anchor" href="#长期运行内存稳定性-持续负载下无泄漏" aria-label="Permalink to &quot;长期运行内存稳定性（持续负载下无泄漏）&quot;">​</a></h2><p>不变量是：在持续负载下，服务器的内存驻留集（RSS）不得无界增长。一个在 10 秒功能测试中通过的、每连接缓慢泄漏，会在一周内让一台嵌入式设备 OOM。</p><p>使用 <code>scripts/performance/long_run_memory.sh</code> 测量，该脚本驱动持续的 <code>wrk -t4 -c100</code> 负载，并每 10 秒采样一次服务器的 RSS。</p><table tabindex="0"><thead><tr><th>经过时间（秒）</th><th>RSS (KB)</th><th>说明</th></tr></thead><tbody><tr><td>10</td><td>5,372</td><td>100 个持续连接</td></tr><tr><td>20</td><td>5,372</td><td></td></tr><tr><td>30</td><td>5,372</td><td></td></tr><tr><td>40</td><td>5,372</td><td></td></tr><tr><td>50</td><td>5,372</td><td></td></tr><tr><td>60</td><td>5,372</td><td></td></tr></tbody></table><p><strong>结果：RSS 平稳——在 60 秒的持续负载、约 20K RPS 下零增长（0 KB），零套接字错误。</strong> 延长运行时间以扩展曲线；预期是一条水平线。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 复现（默认 60 秒；传入更长的时长以获取更长的画像）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/performance/long_run_memory.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span></span></code></pre></div><blockquote><p>这是 ASan 干净保证的运行时补充。ASan 证明沿任何已测试代码路径都不会丢失分配；RSS 画像则证明分配器达到了稳态，且在真实流量下不会漂移。</p></blockquote><h2 id="占用体积" tabindex="-1">占用体积 <a class="header-anchor" href="#占用体积" aria-label="Permalink to &quot;占用体积&quot;">​</a></h2><p>默认 Release 构建（<code>-O2 -DNDEBUG</code>，已 strip），64 位，系统分配器：</p><table tabindex="0"><thead><tr><th>构件</th><th>体积</th></tr></thead><tbody><tr><td>静态库 <code>libuvhttp.a</code></td><td>~257 KB（已 strip）</td></tr><tr><td>示例服务器二进制（<code>test_performance_e2e</code>）</td><td>~1.0 MB（已 strip，静态链接）</td></tr><tr><td>100 连接下的稳态 RSS</td><td>~5.3 MB</td></tr></tbody></table><p>~257 KB 的静态库是嵌入式相关的数字——一个链接 UVHTTP 的设备增加约四分之一兆字节的代码，加上 libuv/mbedtls（仅当相应功能启用时；两者均为编译期可选）。</p><blockquote><p><strong>关于 <code>-Os</code> 的说明：</strong> 项目当前的 Release 模式强制使用 <code>-O2 -DNDEBUG</code>（见 <code>CMakeLists.txt</code>）。如需构建最小体积，覆盖 <code>CMAKE_C_FLAGS_RELEASE</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_BUILD_TYPE=Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      -DCMAKE_C_FLAGS_RELEASE=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-Os -DNDEBUG -ffunction-sections -fdata-sections&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      -DCMAKE_EXE_LINKER_FLAGS=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-Wl,--gc-sections -s&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span></code></pre></div></blockquote><h2 id="冷启动" tabindex="-1">冷启动 <a class="header-anchor" href="#冷启动" aria-label="Permalink to &quot;冷启动&quot;">​</a></h2><p>从进程启动到提供首字节的时间（包含进程启动、事件循环初始化、服务器绑定以及一次请求）：</p><table tabindex="0"><thead><tr><th>指标</th><th>数值</th></tr></thead><tbody><tr><td>启动后首字节</td><td>~310 ms</td></tr></tbody></table><p>适用于按需 / 惰性启动的嵌入式服务以及 serverless 式调用。</p><h2 id="_32-位支持" tabindex="-1">32 位支持 <a class="header-anchor" href="#_32-位支持" aria-label="Permalink to &quot;32 位支持&quot;">​</a></h2><p>UVHTTP 显式支持 32 位目标（v2.5.0 版本主题即为“32 位支持与压缩”）。32 位 CI 构建使用以下配置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-32bit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DCMAKE_C_FLAGS=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-m32 -march=i686 -D_GNU_SOURCE -Wno-format-truncation&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DCMAKE_CXX_FLAGS=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-m32 -march=i686&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ...</span></span></code></pre></div><p>（见 <code>.github/workflows/ci-32bit.yml</code>。）在 32 位下，指针体积减半，连接 / 请求 / 响应结构体也随之缩小，使占用体积适用于资源受限的设备。32 位构建的正确性在 CI 中受把关。</p><h2 id="编译期最小化" tabindex="-1">编译期最小化 <a class="header-anchor" href="#编译期最小化" aria-label="Permalink to &quot;编译期最小化&quot;">​</a></h2><p>占用体积可在编译期配置——只为所用功能付费：</p><table tabindex="0"><thead><tr><th>功能</th><th>CMake 选项</th><th>默认值</th></tr></thead><tbody><tr><td>WebSocket</td><td><code>BUILD_WITH_WEBSOCKET</code></td><td>ON</td></tr><tr><td>TLS（mbedtls）</td><td><code>BUILD_WITH_HTTPS</code></td><td>ON</td></tr><tr><td>静态文件</td><td><code>UVHTTP_FEATURE_STATIC_FILES</code></td><td>ON</td></tr><tr><td>压缩</td><td><code>BUILD_WITH_COMPRESSION</code></td><td>ON</td></tr><tr><td>速率限制</td><td><code>UVHTTP_FEATURE_RATE_LIMIT</code></td><td>ON</td></tr><tr><td>mimalloc 分配器</td><td><code>BUILD_WITH_MIMALLOC</code></td><td>OFF</td></tr></tbody></table><p>一个最小化的嵌入式构建（仅 HTTP/1.1，不含 TLS/WebSocket/静态文件/压缩）通过禁用未用功能，链接一个更小的库。</p><h2 id="为何重要" tabindex="-1">为何重要 <a class="header-anchor" href="#为何重要" aria-label="Permalink to &quot;为何重要&quot;">​</a></h2><p>对于一个设备管理端点或长期运行的边缘服务：</p><ul><li>一个每连接增加 1 KB 的泄漏在 10 秒的 <code>wrk</code> 运行中不可见，但在带 keep-alive 抖动的 100 req/s 下每天耗费约 10 MB。UVHTTP 平稳的 RSS 画像与 ASan 干净状态意味着这一失效模式从构造上被消除。</li><li>一个 ~257 KB、可在 32 位上运行的库，能装进 nginx（一个自带运行时的独立守护进程）所不能之处。</li><li>消毒器干净 + 32 位 + 小占用体积是大多数轻量级 C HTTP 库所不具备的组合——见<a href="./">首页对比表</a>。</li></ul>`,30)])])}const b=a(i,[["render",h]]);export{k as __pageData,b as default};
